from bisect import bisect_left

def longestBitonic(nums):
    def ending_lengths(a):
        tails = []
        out = []
        for x in a:
            i = bisect_left(tails, x)
            if i == len(tails):
                tails.append(x)
            else:
                tails[i] = x
            out.append(i + 1)
        return out

    inc = ending_lengths(nums)
    dec = ending_lengths(nums[::-1])[::-1]
    return max(inc[i] + dec[i] - 1 for i in range(len(nums)))
